<?php if(kd_can('warehouses.manage')): ?><section class="panel customer-form-panel"><div class="form-section-title"><div><h3>Yeni depo ekle</h3><p>Yeni depo eklendiğinde mevcut stoklar otomatik taşınmaz; transfer işlemini kullanın.</p></div></div><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="create"><div class="customer-fields"><label>Depo adı *<input name="name" maxlength="140" required placeholder="Örn. Ankara Şube Deposu"></label><label>Depo kodu *<input name="code" maxlength="40" required pattern="[A-Za-z0-9_-]{2,40}" placeholder="ANKARA"></label><label class="field-wide">Adres<input name="address" maxlength="255"></label></div><div class="form-actions"><button class="btn primary">Depo oluştur</button></div></form></section><?php endif; ?>
